import{_ as o,o as p,c as d,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Files.md","filePath":"manual-zh/Matrix-Files.md","lastUpdated":1785684581000}'),a={name:"manual-zh/Matrix-Files.md"};function t(A,e,i,l,r,_){return p(),d("div",null,[...e[0]||(e[0]=[c('<h3 id="_16-1-矩阵文件" tabindex="-1">16.1 矩阵文件 <a class="header-anchor" href="#_16-1-矩阵文件" aria-label="Permalink to &quot;16.1 矩阵文件&quot;">​</a></h3><p>矩阵文件是一种 SPSS 系统文件，其字典和个案结构符合本节所述。从文件读取矩阵的过程要求矩阵采用矩阵文件格式。写出矩阵的过程也使用这种格式。</p><p>包含矩阵的文本文件可以转换为矩阵文件格式。关于将文本文件作为矩阵文件读取的命令，参见 <a href="./MATRIX-DATA">MATRIX DATA</a>。</p><p>矩阵文件的字典必须按指定顺序包含下列变量：</p><ol><li>零个或多个数值型拆分变量。当 <code>SPLIT FILE</code> 处于激活状态时，过程会包含这些变量。<code>MATRIX DATA</code> 为拆分变量指定格式 F4.0。</li><li><code>ROWTYPE_</code>，一个宽度为 8 的字符串变量。该变量指示某个个案所代表的矩阵或向量的类型。支持的行列类型在下面列出。</li><li>零个或多个数值型因子变量。使用这些变量的过程会将数据划分为多个单元。对于单元内数据，因子变量以非缺失值填充；对于合并数据，它们为缺失值。<code>MATRIX DATA</code> 为因子变量指定格式 F4.0。</li><li><code>VARNAME_</code>，一个字符串变量。矩阵数据为每个连续变量（见下文）包含一行，并按顺序列出每个连续变量的名称。对于向量数据，此列为空。<code>MATRIX DATA</code> 将 <code>VARNAME_</code> 的宽度设为足以容纳任一连续变量名称，但至少 8 字节。</li><li>一个或多个数值型连续变量。这些是经过分析以生成矩阵的数据所涉及的变量。<code>MATRIX DATA</code> 为连续变量指定格式 F10.4。</li></ol><p>矩阵文件中忽略个案权重。</p><h4 id="行类型" tabindex="-1">行类型 <a class="header-anchor" href="#行类型" aria-label="Permalink to &quot;行类型&quot;">​</a></h4><p>矩阵文件支持一组固定的矩阵和向量数据类型。矩阵文件中每个个案的 <code>ROWTYPE_</code> 变量指示其行类型。</p><p>支持的矩阵行类型在下面列出。每种类型都列出了在 <code>ROWTYPE_</code> 中标识它的关键字。所有受支持的矩阵类型均为方阵，即每个矩阵必须对每个连续变量包含一行，由 <code>VARNAME_</code> 变量按与字典相同的顺序依次指示每个连续变量。</p><p><code>CORR</code></p><p>相关系数。</p><p><code>COV</code></p><p>协方差系数。</p><p><code>MAT</code></p><p>通用矩阵。</p><p><code>N_MATRIX</code></p><p>计数。</p><p><code>PROX</code></p><p>邻近度矩阵。</p><p>支持的向量行类型在下面列出，连同其关联的关键字。向量行类型只需要一行，其 <code>VARNAME_</code> 为空：</p><p><code>COUNT</code></p><p>未加权计数。</p><p><code>DFE</code></p><p>自由度。</p><p><code>MEAN</code></p><p>均值。</p><p><code>MSE</code></p><p>均方误差。</p><p><code>N</code></p><p>计数。</p><p><code>STDDEV</code></p><p>标准差。</p><p>矩阵文件中只能出现上述行类型。不过，<code>MATRIX DATA</code> 命令接受下面列出的附加行类型，并在其转换过程中将其转换为矩阵文件行类型：</p><p><code>N_VECTOR</code></p><p><code>N</code> 的同义词。</p><p><code>SD</code></p><p><code>STDDEV</code> 的同义词。</p><p><code>N_SCALAR</code></p><p>从 <code>MATRIX DATA</code> 输入中接受一个数字，并将其作为 <code>N</code> 行写出，该数字在所有连续变量中重复。</p>',39)])])}const n=o(a,[["render",t]]);export{s as __pageData,n as default};
